BEGIN;

-- The existing live pages table was missing fields required by the Page editor.
ALTER TABLE public.pages
  ADD COLUMN IF NOT EXISTS description text,
  ADD COLUMN IF NOT EXISTS content text NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS media jsonb NOT NULL DEFAULT '[]'::jsonb,
  ADD COLUMN IF NOT EXISTS album_id uuid REFERENCES public.albums(id) ON DELETE SET NULL;

ALTER TABLE public.pages
  ALTER COLUMN content SET DEFAULT '',
  ALTER COLUMN media SET DEFAULT '[]'::jsonb;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conrelid = 'public.pages'::regclass
      AND conname = 'pages_media_is_array'
  ) THEN
    ALTER TABLE public.pages
      ADD CONSTRAINT pages_media_is_array CHECK (jsonb_typeof(media) = 'array');
  END IF;
END $$;

ALTER TABLE public.pages ENABLE ROW LEVEL SECURITY;
GRANT SELECT ON public.pages TO anon, authenticated;
GRANT INSERT, UPDATE, DELETE ON public.pages TO authenticated;

DROP POLICY IF EXISTS content_public_read ON public.pages;
CREATE POLICY content_public_read ON public.pages
  FOR SELECT TO anon, authenticated
  USING (visibility = 'public' OR ((SELECT auth.jwt()) -> 'app_metadata' ->> 'role') = 'admin');

DROP POLICY IF EXISTS content_admin_write ON public.pages;
CREATE POLICY content_admin_write ON public.pages
  FOR ALL TO authenticated
  USING (((SELECT auth.jwt()) -> 'app_metadata' ->> 'role') = 'admin')
  WITH CHECK (((SELECT auth.jwt()) -> 'app_metadata' ->> 'role') = 'admin');

-- Insert starter pages only when the URL does not already exist. Existing content is preserved.
INSERT INTO public.pages (title, description, url, content, visibility, media)
VALUES
('গ্রামের পরিচিতি','ডালিমগাড়ী গ্রামের মৌলিক পরিচয়, অবস্থান ও জীবনযাত্রার সারসংক্ষেপ।','village-introduction','<div class="village-page-content"><p class="page-draft-note"><strong>সম্পাদনার নোট:</strong> এটি একটি প্রাথমিক ধারণাগত খসড়া। বাস্তব নাম, সংখ্যা, ঠিকানা, যোগাযোগ ও অন্যান্য স্থানীয় তথ্য যাচাই করে আপডেট করুন।</p><p class="page-lead">ডালিমগাড়ী গ্রামের পরিচয়, মানুষের জীবনযাত্রা, স্থানীয় পরিবেশ ও গুরুত্বপূর্ণ তথ্য এক জায়গায় তুলে ধরার জন্য এই পৃষ্ঠা। গ্রামের নির্ভুল পরিচিতি সম্পূর্ণ করতে স্থানীয়ভাবে যাচাইকৃত তথ্য যোগ করুন।</p><section><h2>এক নজরে</h2><p>গ্রামের ইউনিয়ন/পৌরসভা, উপজেলা, জেলা, বিভাগ, আয়তন এবং নিকটবর্তী গুরুত্বপূর্ণ স্থানের নাম এখানে যোগ করুন।</p></section><section><h2>গ্রামের বৈশিষ্ট্য</h2><p>গ্রামের প্রধান পেশা, সামাজিক জীবন, প্রাকৃতিক পরিবেশ ও পরিচিত বৈশিষ্ট্য সংক্ষেপে লিখুন।</p></section><section><h2>তথ্য হালনাগাদ</h2><p>নতুন তথ্য, সংশোধন বা প্রাসঙ্গিক ছবি যোগ করতে এই পৃষ্ঠাটি ড্যাশবোর্ডের Page সেকশন থেকে সম্পাদনা করুন। নির্দিষ্ট তথ্যের উৎস ও সর্বশেষ হালনাগাদের তারিখ উল্লেখ করা ভালো।</p></section><style>.village-page-content{color:#263238;line-height:1.8;font-size:16px}.village-page-content .page-draft-note{padding:12px 14px;border-left:4px solid #b7791f;background:#fff8e6;border-radius:6px;font-size:14px}.village-page-content .page-lead{font-size:18px;color:#374151}.village-page-content section{margin:22px 0;padding:18px 20px;border:1px solid #e5e7eb;border-radius:12px;background:#fff}.village-page-content h2{margin:0 0 10px;color:#234e52;font-size:22px}.village-page-content p{margin:0 0 10px}.village-page-content p:last-child{margin-bottom:0}@media(max-width:600px){.village-page-content section{padding:14px}.village-page-content h2{font-size:19px}.village-page-content .page-lead{font-size:16px}}</style></div>','public','[]'::jsonb),
('গ্রামের ইতিহাস','গ্রামের উৎপত্তি, নামকরণ, ঐতিহাসিক ঘটনা ও স্মরণীয় পরিবর্তনের বিবরণ।','village-history','<div class="village-page-content"><p class="page-draft-note"><strong>সম্পাদনার নোট:</strong> এটি একটি প্রাথমিক ধারণাগত খসড়া। বাস্তব নাম, সংখ্যা, ঠিকানা, যোগাযোগ ও অন্যান্য স্থানীয় তথ্য যাচাই করে আপডেট করুন।</p><p class="page-lead">একটি গ্রামের ইতিহাস গড়ে ওঠে মানুষের স্মৃতি, বসতি, সামাজিক পরিবর্তন ও স্থানীয় ঐতিহ্যের মধ্য দিয়ে। এই পৃষ্ঠায় ডালিমগাড়ী গ্রামের ইতিহাস সংরক্ষণ করা হবে।</p><section><h2>নামকরণের ইতিহাস</h2><p>‘ডালিমগাড়ী’ নামের উৎপত্তি সম্পর্কে প্রচলিত ব্যাখ্যা থাকলে তা উল্লেখ করুন এবং প্রবীণ বাসিন্দা বা নির্ভরযোগ্য নথির মাধ্যমে যাচাই করুন।</p></section><section><h2>গুরুত্বপূর্ণ সময় ও ঘটনা</h2><p>পুরোনো বসতি, যোগাযোগব্যবস্থার পরিবর্তন, শিক্ষা প্রতিষ্ঠানের সূচনা এবং স্মরণীয় ঘটনার সাল-তারিখসহ তথ্য যোগ করুন।</p></section><section><h2>তথ্য হালনাগাদ</h2><p>নতুন তথ্য, সংশোধন বা প্রাসঙ্গিক ছবি যোগ করতে এই পৃষ্ঠাটি ড্যাশবোর্ডের Page সেকশন থেকে সম্পাদনা করুন। নির্দিষ্ট তথ্যের উৎস ও সর্বশেষ হালনাগাদের তারিখ উল্লেখ করা ভালো।</p></section><style>.village-page-content{color:#263238;line-height:1.8;font-size:16px}.village-page-content .page-draft-note{padding:12px 14px;border-left:4px solid #b7791f;background:#fff8e6;border-radius:6px;font-size:14px}.village-page-content .page-lead{font-size:18px;color:#374151}.village-page-content section{margin:22px 0;padding:18px 20px;border:1px solid #e5e7eb;border-radius:12px;background:#fff}.village-page-content h2{margin:0 0 10px;color:#234e52;font-size:22px}.village-page-content p{margin:0 0 10px}.village-page-content p:last-child{margin-bottom:0}@media(max-width:600px){.village-page-content section{padding:14px}.village-page-content h2{font-size:19px}.village-page-content .page-lead{font-size:16px}}</style></div>','public','[]'::jsonb),
('ভৌগোলিক পরিচিতি','গ্রামের অবস্থান, সীমানা, ভূমির ধরন ও প্রাকৃতিক বৈশিষ্ট্য।','geography','<div class="village-page-content"><p class="page-draft-note"><strong>সম্পাদনার নোট:</strong> এটি একটি প্রাথমিক ধারণাগত খসড়া। বাস্তব নাম, সংখ্যা, ঠিকানা, যোগাযোগ ও অন্যান্য স্থানীয় তথ্য যাচাই করে আপডেট করুন।</p><p class="page-lead">এই পৃষ্ঠায় গ্রামের ভৌগোলিক অবস্থান ও প্রাকৃতিক পরিবেশ সম্পর্কে তথ্য সাজানো হবে। প্রশাসনিক অবস্থান ও সীমানা নির্ভরযোগ্য মানচিত্র বা সরকারি নথি থেকে যাচাই করে যোগ করুন।</p><section><h2>অবস্থান ও সীমানা</h2><p>বিভাগ, জেলা, উপজেলা, ইউনিয়ন এবং উত্তর-দক্ষিণ-পূর্ব-পশ্চিমের সংলগ্ন এলাকা লিখুন।</p></section><section><h2>ভূপ্রকৃতি ও পরিবেশ</h2><p>ভূমির ধরন, জলাশয়, নদী-খাল, গাছপালা এবং বর্ষা ও শুষ্ক মৌসুমের বৈশিষ্ট্য বর্ণনা করুন।</p></section><section><h2>তথ্য হালনাগাদ</h2><p>নতুন তথ্য, সংশোধন বা প্রাসঙ্গিক ছবি যোগ করতে এই পৃষ্ঠাটি ড্যাশবোর্ডের Page সেকশন থেকে সম্পাদনা করুন। নির্দিষ্ট তথ্যের উৎস ও সর্বশেষ হালনাগাদের তারিখ উল্লেখ করা ভালো।</p></section><style>.village-page-content{color:#263238;line-height:1.8;font-size:16px}.village-page-content .page-draft-note{padding:12px 14px;border-left:4px solid #b7791f;background:#fff8e6;border-radius:6px;font-size:14px}.village-page-content .page-lead{font-size:18px;color:#374151}.village-page-content section{margin:22px 0;padding:18px 20px;border:1px solid #e5e7eb;border-radius:12px;background:#fff}.village-page-content h2{margin:0 0 10px;color:#234e52;font-size:22px}.village-page-content p{margin:0 0 10px}.village-page-content p:last-child{margin-bottom:0}@media(max-width:600px){.village-page-content section{padding:14px}.village-page-content h2{font-size:19px}.village-page-content .page-lead{font-size:16px}}</style></div>','public','[]'::jsonb),
('জনসংখ্যা ও পরিসংখ্যান','জনসংখ্যা, পরিবার, বসতি ও অন্যান্য যাচাইকৃত স্থানীয় পরিসংখ্যান।','population','<div class="village-page-content"><p class="page-draft-note"><strong>সম্পাদনার নোট:</strong> এটি একটি প্রাথমিক ধারণাগত খসড়া। বাস্তব নাম, সংখ্যা, ঠিকানা, যোগাযোগ ও অন্যান্য স্থানীয় তথ্য যাচাই করে আপডেট করুন।</p><p class="page-lead">গ্রামের জনসংখ্যা ও বসতি-সম্পর্কিত তথ্য সময়ের সঙ্গে পরিবর্তিত হয়। তাই এখানে সর্বশেষ নির্ভরযোগ্য উৎস, তথ্য সংগ্রহের বছর এবং প্রযোজ্য হলে পরিসংখ্যানের সংজ্ঞা উল্লেখ করা উচিত।</p><section><h2>মূল পরিসংখ্যান</h2><p>মোট জনসংখ্যা, পরিবারের সংখ্যা, ওয়ার্ডভিত্তিক তথ্য এবং তথ্যের বছর নির্ভরযোগ্য উৎসসহ যোগ করুন।</p></section><section><h2>তথ্যের উৎস</h2><p>জনশুমারি, স্থানীয় প্রশাসন বা যাচাইকৃত জরিপের নাম ও প্রকাশের তারিখ উল্লেখ করুন। অনুমানকে সরকারি পরিসংখ্যান হিসেবে দেখাবেন না।</p></section><section><h2>তথ্য হালনাগাদ</h2><p>নতুন তথ্য, সংশোধন বা প্রাসঙ্গিক ছবি যোগ করতে এই পৃষ্ঠাটি ড্যাশবোর্ডের Page সেকশন থেকে সম্পাদনা করুন। নির্দিষ্ট তথ্যের উৎস ও সর্বশেষ হালনাগাদের তারিখ উল্লেখ করা ভালো।</p></section><style>.village-page-content{color:#263238;line-height:1.8;font-size:16px}.village-page-content .page-draft-note{padding:12px 14px;border-left:4px solid #b7791f;background:#fff8e6;border-radius:6px;font-size:14px}.village-page-content .page-lead{font-size:18px;color:#374151}.village-page-content section{margin:22px 0;padding:18px 20px;border:1px solid #e5e7eb;border-radius:12px;background:#fff}.village-page-content h2{margin:0 0 10px;color:#234e52;font-size:22px}.village-page-content p{margin:0 0 10px}.village-page-content p:last-child{margin-bottom:0}@media(max-width:600px){.village-page-content section{padding:14px}.village-page-content h2{font-size:19px}.village-page-content .page-lead{font-size:16px}}</style></div>','public','[]'::jsonb),
('গ্রাম মানচিত্র','গ্রামের অবস্থান, প্রবেশপথ ও গুরুত্বপূর্ণ স্থানের মানচিত্র।','map','<div class="village-page-content"><p class="page-draft-note"><strong>সম্পাদনার নোট:</strong> এটি একটি প্রাথমিক ধারণাগত খসড়া। বাস্তব নাম, সংখ্যা, ঠিকানা, যোগাযোগ ও অন্যান্য স্থানীয় তথ্য যাচাই করে আপডেট করুন।</p><p class="page-lead">এই পৃষ্ঠার মাধ্যমে দর্শনার্থীরা গ্রামের অবস্থান এবং গুরুত্বপূর্ণ স্থানগুলো সহজে খুঁজে পেতে পারবেন। প্রকাশের আগে মানচিত্রের পিন ও স্থানের নাম যাচাই করুন।</p><section><h2>অবস্থান</h2><p>যাচাইকৃত মানচিত্র লিংক বা এমবেড যোগ করুন এবং গ্রামের কেন্দ্র বা প্রবেশপথের সঠিক অবস্থান চিহ্নিত করুন।</p></section><section><h2>গুরুত্বপূর্ণ স্থান</h2><p>শিক্ষা প্রতিষ্ঠান, বাজার, স্বাস্থ্যকেন্দ্র, ধর্মীয় প্রতিষ্ঠান এবং প্রধান সড়কের অবস্থান আলাদা করে চিহ্নিত করা যেতে পারে।</p></section><section><h2>তথ্য হালনাগাদ</h2><p>নতুন তথ্য, সংশোধন বা প্রাসঙ্গিক ছবি যোগ করতে এই পৃষ্ঠাটি ড্যাশবোর্ডের Page সেকশন থেকে সম্পাদনা করুন। নির্দিষ্ট তথ্যের উৎস ও সর্বশেষ হালনাগাদের তারিখ উল্লেখ করা ভালো।</p></section><style>.village-page-content{color:#263238;line-height:1.8;font-size:16px}.village-page-content .page-draft-note{padding:12px 14px;border-left:4px solid #b7791f;background:#fff8e6;border-radius:6px;font-size:14px}.village-page-content .page-lead{font-size:18px;color:#374151}.village-page-content section{margin:22px 0;padding:18px 20px;border:1px solid #e5e7eb;border-radius:12px;background:#fff}.village-page-content h2{margin:0 0 10px;color:#234e52;font-size:22px}.village-page-content p{margin:0 0 10px}.village-page-content p:last-child{margin-bottom:0}@media(max-width:600px){.village-page-content section{padding:14px}.village-page-content h2{font-size:19px}.village-page-content .page-lead{font-size:16px}}</style></div>','public','[]'::jsonb),
('গ্রামের বিশিষ্ট ব্যক্তিবর্গ','গ্রামের উল্লেখযোগ্য ব্যক্তিদের পরিচিতি ও অবদান।','notable-people','<div class="village-page-content"><p class="page-draft-note"><strong>সম্পাদনার নোট:</strong> এটি একটি প্রাথমিক ধারণাগত খসড়া। বাস্তব নাম, সংখ্যা, ঠিকানা, যোগাযোগ ও অন্যান্য স্থানীয় তথ্য যাচাই করে আপডেট করুন।</p><p class="page-lead">গ্রামের বিভিন্ন ক্ষেত্রে অবদান রাখা ব্যক্তিদের পরিচিতি সংরক্ষণের জন্য এই পৃষ্ঠা। ব্যক্তির নাম, পরিচয় ও অবদান প্রকাশের আগে তথ্য যাচাই এবং প্রয়োজনীয় সম্মতি নেওয়া উচিত।</p><section><h2>পরিচিতি</h2><p>ব্যক্তির নাম, পরিচিত ক্ষেত্র, প্রাসঙ্গিক জীবনী এবং গ্রামের সঙ্গে তাঁর সম্পর্ক লিখুন।</p></section><section><h2>অবদান ও সূত্র</h2><p>শিক্ষা, সমাজসেবা, সংস্কৃতি, ক্রীড়া বা অন্যান্য ক্ষেত্রে যাচাইযোগ্য অবদান উল্লেখ করুন। ব্যক্তিগত বা সংবেদনশীল তথ্য অনুমতি ছাড়া প্রকাশ করবেন না।</p></section><section><h2>তথ্য হালনাগাদ</h2><p>নতুন তথ্য, সংশোধন বা প্রাসঙ্গিক ছবি যোগ করতে এই পৃষ্ঠাটি ড্যাশবোর্ডের Page সেকশন থেকে সম্পাদনা করুন। নির্দিষ্ট তথ্যের উৎস ও সর্বশেষ হালনাগাদের তারিখ উল্লেখ করা ভালো।</p></section><style>.village-page-content{color:#263238;line-height:1.8;font-size:16px}.village-page-content .page-draft-note{padding:12px 14px;border-left:4px solid #b7791f;background:#fff8e6;border-radius:6px;font-size:14px}.village-page-content .page-lead{font-size:18px;color:#374151}.village-page-content section{margin:22px 0;padding:18px 20px;border:1px solid #e5e7eb;border-radius:12px;background:#fff}.village-page-content h2{margin:0 0 10px;color:#234e52;font-size:22px}.village-page-content p{margin:0 0 10px}.village-page-content p:last-child{margin-bottom:0}@media(max-width:600px){.village-page-content section{padding:14px}.village-page-content h2{font-size:19px}.village-page-content .page-lead{font-size:16px}}</style></div>','public','[]'::jsonb),
('শিক্ষা প্রতিষ্ঠান','গ্রামের স্কুল, কলেজ, মাদ্রাসা ও অন্যান্য শিক্ষা প্রতিষ্ঠানের তথ্য।','education','<div class="village-page-content"><p class="page-draft-note"><strong>সম্পাদনার নোট:</strong> এটি একটি প্রাথমিক ধারণাগত খসড়া। বাস্তব নাম, সংখ্যা, ঠিকানা, যোগাযোগ ও অন্যান্য স্থানীয় তথ্য যাচাই করে আপডেট করুন।</p><p class="page-lead">শিক্ষা প্রতিষ্ঠান সম্পর্কিত হালনাগাদ তথ্য শিক্ষার্থী, অভিভাবক ও গ্রামের মানুষের কাজে আসতে পারে। প্রতিটি প্রতিষ্ঠানের তথ্য সংশ্লিষ্ট কর্তৃপক্ষের সঙ্গে মিলিয়ে নিন।</p><section><h2>প্রতিষ্ঠানের তালিকা</h2><p>প্রতিষ্ঠানের নাম, ধরন, ঠিকানা, যোগাযোগের তথ্য এবং প্রযোজ্য হলে EIIN বা স্বীকৃতির তথ্য যোগ করুন।</p></section><section><h2>শিক্ষা কার্যক্রম</h2><p>শ্রেণি/কোর্স, ভর্তি-সংক্রান্ত ঘোষণা এবং বিশেষ কার্যক্রমের তথ্য কেবল নিশ্চিত হলে প্রকাশ করুন।</p></section><section><h2>তথ্য হালনাগাদ</h2><p>নতুন তথ্য, সংশোধন বা প্রাসঙ্গিক ছবি যোগ করতে এই পৃষ্ঠাটি ড্যাশবোর্ডের Page সেকশন থেকে সম্পাদনা করুন। নির্দিষ্ট তথ্যের উৎস ও সর্বশেষ হালনাগাদের তারিখ উল্লেখ করা ভালো।</p></section><style>.village-page-content{color:#263238;line-height:1.8;font-size:16px}.village-page-content .page-draft-note{padding:12px 14px;border-left:4px solid #b7791f;background:#fff8e6;border-radius:6px;font-size:14px}.village-page-content .page-lead{font-size:18px;color:#374151}.village-page-content section{margin:22px 0;padding:18px 20px;border:1px solid #e5e7eb;border-radius:12px;background:#fff}.village-page-content h2{margin:0 0 10px;color:#234e52;font-size:22px}.village-page-content p{margin:0 0 10px}.village-page-content p:last-child{margin-bottom:0}@media(max-width:600px){.village-page-content section{padding:14px}.village-page-content h2{font-size:19px}.village-page-content .page-lead{font-size:16px}}</style></div>','public','[]'::jsonb),
('ধর্মীয় প্রতিষ্ঠান','গ্রামের মসজিদ, মন্দির ও অন্যান্য ধর্মীয় প্রতিষ্ঠানের পরিচিতি।','religious-institutions','<div class="village-page-content"><p class="page-draft-note"><strong>সম্পাদনার নোট:</strong> এটি একটি প্রাথমিক ধারণাগত খসড়া। বাস্তব নাম, সংখ্যা, ঠিকানা, যোগাযোগ ও অন্যান্য স্থানীয় তথ্য যাচাই করে আপডেট করুন।</p><p class="page-lead">গ্রামের ধর্মীয় প্রতিষ্ঠানগুলো স্থানীয় জীবন ও সামাজিক কর্মকাণ্ডের অংশ। এই পৃষ্ঠায় প্রতিষ্ঠানগুলোর নাম, অবস্থান এবং প্রকাশযোগ্য যোগাযোগের তথ্য নিরপেক্ষভাবে উপস্থাপন করুন।</p><section><h2>প্রতিষ্ঠানের পরিচয়</h2><p>প্রতিষ্ঠানের নাম, ধরন, অবস্থান এবং পরিচিতির সংক্ষিপ্ত বিবরণ যোগ করুন।</p></section><section><h2>যোগাযোগ ও সময়সূচি</h2><p>অনুমোদিত যোগাযোগের তথ্য এবং কর্তৃপক্ষ নিশ্চিত করা সময়সূচি থাকলে প্রকাশ করুন। সময়সূচি পরিবর্তনশীল হলে সর্বশেষ হালনাগাদের তারিখ দিন।</p></section><section><h2>তথ্য হালনাগাদ</h2><p>নতুন তথ্য, সংশোধন বা প্রাসঙ্গিক ছবি যোগ করতে এই পৃষ্ঠাটি ড্যাশবোর্ডের Page সেকশন থেকে সম্পাদনা করুন। নির্দিষ্ট তথ্যের উৎস ও সর্বশেষ হালনাগাদের তারিখ উল্লেখ করা ভালো।</p></section><style>.village-page-content{color:#263238;line-height:1.8;font-size:16px}.village-page-content .page-draft-note{padding:12px 14px;border-left:4px solid #b7791f;background:#fff8e6;border-radius:6px;font-size:14px}.village-page-content .page-lead{font-size:18px;color:#374151}.village-page-content section{margin:22px 0;padding:18px 20px;border:1px solid #e5e7eb;border-radius:12px;background:#fff}.village-page-content h2{margin:0 0 10px;color:#234e52;font-size:22px}.village-page-content p{margin:0 0 10px}.village-page-content p:last-child{margin-bottom:0}@media(max-width:600px){.village-page-content section{padding:14px}.village-page-content h2{font-size:19px}.village-page-content .page-lead{font-size:16px}}</style></div>','public','[]'::jsonb),
('সামাজিক সংগঠন','স্থানীয় ক্লাব, সমিতি, স্বেচ্ছাসেবী দল ও সামাজিক উদ্যোগ।','organizations','<div class="village-page-content"><p class="page-draft-note"><strong>সম্পাদনার নোট:</strong> এটি একটি প্রাথমিক ধারণাগত খসড়া। বাস্তব নাম, সংখ্যা, ঠিকানা, যোগাযোগ ও অন্যান্য স্থানীয় তথ্য যাচাই করে আপডেট করুন।</p><p class="page-lead">গ্রামের সামাজিক সংগঠনগুলো জনকল্যাণ, সংস্কৃতি, খেলাধুলা ও পারস্পরিক সহযোগিতায় ভূমিকা রাখতে পারে। সক্রিয় সংগঠনগুলোর তথ্য যাচাই করে এই পৃষ্ঠায় সাজানো হবে।</p><section><h2>সংগঠনের তথ্য</h2><p>সংগঠনের নাম, উদ্দেশ্য, প্রতিষ্ঠার বছর (জানা ও যাচাই করা থাকলে), কার্যক্রম এবং প্রকাশযোগ্য যোগাযোগের তথ্য লিখুন।</p></section><section><h2>অংশগ্রহণ</h2><p>নতুন সদস্য হওয়া বা স্বেচ্ছাসেবায় যুক্ত হওয়ার নিয়ম সংগঠনের অনুমোদন নিয়ে প্রকাশ করুন।</p></section><section><h2>তথ্য হালনাগাদ</h2><p>নতুন তথ্য, সংশোধন বা প্রাসঙ্গিক ছবি যোগ করতে এই পৃষ্ঠাটি ড্যাশবোর্ডের Page সেকশন থেকে সম্পাদনা করুন। নির্দিষ্ট তথ্যের উৎস ও সর্বশেষ হালনাগাদের তারিখ উল্লেখ করা ভালো।</p></section><style>.village-page-content{color:#263238;line-height:1.8;font-size:16px}.village-page-content .page-draft-note{padding:12px 14px;border-left:4px solid #b7791f;background:#fff8e6;border-radius:6px;font-size:14px}.village-page-content .page-lead{font-size:18px;color:#374151}.village-page-content section{margin:22px 0;padding:18px 20px;border:1px solid #e5e7eb;border-radius:12px;background:#fff}.village-page-content h2{margin:0 0 10px;color:#234e52;font-size:22px}.village-page-content p{margin:0 0 10px}.village-page-content p:last-child{margin-bottom:0}@media(max-width:600px){.village-page-content section{padding:14px}.village-page-content h2{font-size:19px}.village-page-content .page-lead{font-size:16px}}</style></div>','public','[]'::jsonb),
('জনপ্রতিনিধি ও প্রশাসন','স্থানীয় প্রশাসন, জনপ্রতিনিধি ও সরকারি সেবার যোগাযোগের তথ্য।','administration','<div class="village-page-content"><p class="page-draft-note"><strong>সম্পাদনার নোট:</strong> এটি একটি প্রাথমিক ধারণাগত খসড়া। বাস্তব নাম, সংখ্যা, ঠিকানা, যোগাযোগ ও অন্যান্য স্থানীয় তথ্য যাচাই করে আপডেট করুন।</p><p class="page-lead">এই পৃষ্ঠায় গ্রামের সঙ্গে সম্পর্কিত প্রশাসনিক কাঠামো এবং সরকারি সেবার যোগাযোগের তথ্য রাখা হবে। পদধারীর নাম ও মেয়াদ পরিবর্তিত হতে পারে, তাই নিয়মিত যাচাই প্রয়োজন।</p><section><h2>প্রশাসনিক পরিচয়</h2><p>ইউনিয়ন/পৌরসভা, উপজেলা, জেলা এবং সংশ্লিষ্ট সরকারি দপ্তরের নাম নির্ভরযোগ্য সরকারি উৎস থেকে যোগ করুন।</p></section><section><h2>প্রতিনিধি ও সেবা</h2><p>বর্তমান জনপ্রতিনিধির নাম, দায়িত্ব, অফিসের ঠিকানা ও প্রকাশ্য যোগাযোগের তথ্য যাচাই করে প্রকাশ করুন।</p></section><section><h2>তথ্য হালনাগাদ</h2><p>নতুন তথ্য, সংশোধন বা প্রাসঙ্গিক ছবি যোগ করতে এই পৃষ্ঠাটি ড্যাশবোর্ডের Page সেকশন থেকে সম্পাদনা করুন। নির্দিষ্ট তথ্যের উৎস ও সর্বশেষ হালনাগাদের তারিখ উল্লেখ করা ভালো।</p></section><style>.village-page-content{color:#263238;line-height:1.8;font-size:16px}.village-page-content .page-draft-note{padding:12px 14px;border-left:4px solid #b7791f;background:#fff8e6;border-radius:6px;font-size:14px}.village-page-content .page-lead{font-size:18px;color:#374151}.village-page-content section{margin:22px 0;padding:18px 20px;border:1px solid #e5e7eb;border-radius:12px;background:#fff}.village-page-content h2{margin:0 0 10px;color:#234e52;font-size:22px}.village-page-content p{margin:0 0 10px}.village-page-content p:last-child{margin-bottom:0}@media(max-width:600px){.village-page-content section{padding:14px}.village-page-content h2{font-size:19px}.village-page-content .page-lead{font-size:16px}}</style></div>','public','[]'::jsonb),
('যোগাযোগব্যবস্থা','গ্রামে পৌঁছানোর উপায়, প্রধান সড়ক ও স্থানীয় যাতায়াত।','transport','<div class="village-page-content"><p class="page-draft-note"><strong>সম্পাদনার নোট:</strong> এটি একটি প্রাথমিক ধারণাগত খসড়া। বাস্তব নাম, সংখ্যা, ঠিকানা, যোগাযোগ ও অন্যান্য স্থানীয় তথ্য যাচাই করে আপডেট করুন।</p><p class="page-lead">গ্রামে আসা-যাওয়া সহজ করতে পরিচিত সড়ক, নিকটবর্তী পরিবহনকেন্দ্র এবং স্থানীয় যানবাহনের তথ্য এখানে রাখা হবে। রুট ও সময়সূচি পরিবর্তন হলে তথ্য হালনাগাদ করুন।</p><section><h2>যাতায়াতের উপায়</h2><p>নিকটবর্তী বাসস্ট্যান্ড, রেলস্টেশন বা অন্যান্য পরিবহনকেন্দ্র এবং সেখান থেকে গ্রামের রুট যাচাই করে লিখুন।</p></section><section><h2>স্থানীয় চলাচল</h2><p>স্থানীয়ভাবে চলাচলকারী যানবাহন, আনুমানিক ভ্রমণসময় ও রাস্তার অবস্থা উল্লেখ করলে তথ্যের তারিখও দিন।</p></section><section><h2>তথ্য হালনাগাদ</h2><p>নতুন তথ্য, সংশোধন বা প্রাসঙ্গিক ছবি যোগ করতে এই পৃষ্ঠাটি ড্যাশবোর্ডের Page সেকশন থেকে সম্পাদনা করুন। নির্দিষ্ট তথ্যের উৎস ও সর্বশেষ হালনাগাদের তারিখ উল্লেখ করা ভালো।</p></section><style>.village-page-content{color:#263238;line-height:1.8;font-size:16px}.village-page-content .page-draft-note{padding:12px 14px;border-left:4px solid #b7791f;background:#fff8e6;border-radius:6px;font-size:14px}.village-page-content .page-lead{font-size:18px;color:#374151}.village-page-content section{margin:22px 0;padding:18px 20px;border:1px solid #e5e7eb;border-radius:12px;background:#fff}.village-page-content h2{margin:0 0 10px;color:#234e52;font-size:22px}.village-page-content p{margin:0 0 10px}.village-page-content p:last-child{margin-bottom:0}@media(max-width:600px){.village-page-content section{padding:14px}.village-page-content h2{font-size:19px}.village-page-content .page-lead{font-size:16px}}</style></div>','public','[]'::jsonb),
('বাজার ও ব্যবসা','গ্রামের বাজার, দোকান, সেবা ও স্থানীয় ব্যবসা প্রতিষ্ঠান।','markets','<div class="village-page-content"><p class="page-draft-note"><strong>সম্পাদনার নোট:</strong> এটি একটি প্রাথমিক ধারণাগত খসড়া। বাস্তব নাম, সংখ্যা, ঠিকানা, যোগাযোগ ও অন্যান্য স্থানীয় তথ্য যাচাই করে আপডেট করুন।</p><p class="page-lead">স্থানীয় বাজার ও ব্যবসার তথ্য বাসিন্দা এবং দর্শনার্থীদের দৈনন্দিন প্রয়োজন মেটাতে সহায়ক। প্রতিষ্ঠানগুলোর নাম, অবস্থান ও খোলার সময় মালিক বা কর্তৃপক্ষের কাছ থেকে যাচাই করুন।</p><section><h2>বাজারের পরিচিতি</h2><p>বাজারের নাম, অবস্থান, সাপ্তাহিক হাটের দিন (যদি থাকে) এবং সাধারণত পাওয়া যায় এমন পণ্যের তথ্য যোগ করুন।</p></section><section><h2>ব্যবসা প্রতিষ্ঠান</h2><p>দোকান বা সেবাদাতার নাম, ঠিকানা ও সম্মতিপ্রাপ্ত যোগাযোগের তথ্য প্রকাশ করুন। যাচাই না করা মূল্য বা সেবার দাবি এড়িয়ে চলুন।</p></section><section><h2>তথ্য হালনাগাদ</h2><p>নতুন তথ্য, সংশোধন বা প্রাসঙ্গিক ছবি যোগ করতে এই পৃষ্ঠাটি ড্যাশবোর্ডের Page সেকশন থেকে সম্পাদনা করুন। নির্দিষ্ট তথ্যের উৎস ও সর্বশেষ হালনাগাদের তারিখ উল্লেখ করা ভালো।</p></section><style>.village-page-content{color:#263238;line-height:1.8;font-size:16px}.village-page-content .page-draft-note{padding:12px 14px;border-left:4px solid #b7791f;background:#fff8e6;border-radius:6px;font-size:14px}.village-page-content .page-lead{font-size:18px;color:#374151}.village-page-content section{margin:22px 0;padding:18px 20px;border:1px solid #e5e7eb;border-radius:12px;background:#fff}.village-page-content h2{margin:0 0 10px;color:#234e52;font-size:22px}.village-page-content p{margin:0 0 10px}.village-page-content p:last-child{margin-bottom:0}@media(max-width:600px){.village-page-content section{padding:14px}.village-page-content h2{font-size:19px}.village-page-content .page-lead{font-size:16px}}</style></div>','public','[]'::jsonb),
('স্বাস্থ্যসেবা','হাসপাতাল, ক্লিনিক, ফার্মেসি ও প্রাথমিক স্বাস্থ্যসেবার তথ্য।','healthcare','<div class="village-page-content"><p class="page-draft-note"><strong>সম্পাদনার নোট:</strong> এটি একটি প্রাথমিক ধারণাগত খসড়া। বাস্তব নাম, সংখ্যা, ঠিকানা, যোগাযোগ ও অন্যান্য স্থানীয় তথ্য যাচাই করে আপডেট করুন।</p><p class="page-lead">স্বাস্থ্যসেবা কোথায় পাওয়া যায় তা জানা জরুরি। এই পৃষ্ঠায় কেবল যাচাইকৃত প্রতিষ্ঠানের অবস্থান ও যোগাযোগের তথ্য দিন; এটি চিকিৎসকের পরামর্শের বিকল্প নয়।</p><section><h2>স্বাস্থ্যকেন্দ্র</h2><p>নিকটবর্তী হাসপাতাল, ক্লিনিক, কমিউনিটি ক্লিনিক বা স্বাস্থ্যকেন্দ্রের নাম, ঠিকানা ও যোগাযোগের তথ্য যোগ করুন।</p></section><section><h2>জরুরি প্রয়োজন</h2><p>স্থানীয়ভাবে যাচাইকৃত জরুরি যোগাযোগ ও সেবার সময়সূচি প্রকাশ করুন। গুরুতর জরুরি অবস্থায় স্থানীয় জরুরি সেবার সঙ্গে সরাসরি যোগাযোগের নির্দেশ দিন।</p></section><section><h2>তথ্য হালনাগাদ</h2><p>নতুন তথ্য, সংশোধন বা প্রাসঙ্গিক ছবি যোগ করতে এই পৃষ্ঠাটি ড্যাশবোর্ডের Page সেকশন থেকে সম্পাদনা করুন। নির্দিষ্ট তথ্যের উৎস ও সর্বশেষ হালনাগাদের তারিখ উল্লেখ করা ভালো।</p></section><style>.village-page-content{color:#263238;line-height:1.8;font-size:16px}.village-page-content .page-draft-note{padding:12px 14px;border-left:4px solid #b7791f;background:#fff8e6;border-radius:6px;font-size:14px}.village-page-content .page-lead{font-size:18px;color:#374151}.village-page-content section{margin:22px 0;padding:18px 20px;border:1px solid #e5e7eb;border-radius:12px;background:#fff}.village-page-content h2{margin:0 0 10px;color:#234e52;font-size:22px}.village-page-content p{margin:0 0 10px}.village-page-content p:last-child{margin-bottom:0}@media(max-width:600px){.village-page-content section{padding:14px}.village-page-content h2{font-size:19px}.village-page-content .page-lead{font-size:16px}}</style></div>','public','[]'::jsonb),
('কৃষি ও অর্থনীতি','কৃষি, প্রধান ফসল, পেশা ও স্থানীয় অর্থনৈতিক কর্মকাণ্ড।','agriculture-economy','<div class="village-page-content"><p class="page-draft-note"><strong>সম্পাদনার নোট:</strong> এটি একটি প্রাথমিক ধারণাগত খসড়া। বাস্তব নাম, সংখ্যা, ঠিকানা, যোগাযোগ ও অন্যান্য স্থানীয় তথ্য যাচাই করে আপডেট করুন।</p><p class="page-lead">গ্রামের অর্থনৈতিক জীবন বুঝতে কৃষি, শ্রম, ক্ষুদ্র ব্যবসা এবং অন্যান্য জীবিকার তথ্য গুরুত্বপূর্ণ। স্থানীয় কৃষক ও সংশ্লিষ্ট দপ্তরের তথ্যের ভিত্তিতে এই পৃষ্ঠা পূরণ করুন।</p><section><h2>কৃষি ও উৎপাদন</h2><p>প্রধান ফসল, মৌসুমি চাষ, সেচব্যবস্থা এবং কৃষি-সম্পর্কিত চ্যালেঞ্জ স্থানীয়ভাবে যাচাই করে লিখুন।</p></section><section><h2>জীবিকা ও বাজার</h2><p>গ্রামের প্রধান পেশা, ক্ষুদ্র উদ্যোগ, কর্মসংস্থান এবং পণ্য বিক্রির বাজার সম্পর্কে নিরপেক্ষ বিবরণ দিন।</p></section><section><h2>তথ্য হালনাগাদ</h2><p>নতুন তথ্য, সংশোধন বা প্রাসঙ্গিক ছবি যোগ করতে এই পৃষ্ঠাটি ড্যাশবোর্ডের Page সেকশন থেকে সম্পাদনা করুন। নির্দিষ্ট তথ্যের উৎস ও সর্বশেষ হালনাগাদের তারিখ উল্লেখ করা ভালো।</p></section><style>.village-page-content{color:#263238;line-height:1.8;font-size:16px}.village-page-content .page-draft-note{padding:12px 14px;border-left:4px solid #b7791f;background:#fff8e6;border-radius:6px;font-size:14px}.village-page-content .page-lead{font-size:18px;color:#374151}.village-page-content section{margin:22px 0;padding:18px 20px;border:1px solid #e5e7eb;border-radius:12px;background:#fff}.village-page-content h2{margin:0 0 10px;color:#234e52;font-size:22px}.village-page-content p{margin:0 0 10px}.village-page-content p:last-child{margin-bottom:0}@media(max-width:600px){.village-page-content section{padding:14px}.village-page-content h2{font-size:19px}.village-page-content .page-lead{font-size:16px}}</style></div>','public','[]'::jsonb),
('ডাকঘর ও জরুরি যোগাযোগ','ডাকঘর ও যাচাইকৃত জরুরি সেবা-সংক্রান্ত যোগাযোগ।','emergency-contacts','<div class="village-page-content"><p class="page-draft-note"><strong>সম্পাদনার নোট:</strong> এটি একটি প্রাথমিক ধারণাগত খসড়া। বাস্তব নাম, সংখ্যা, ঠিকানা, যোগাযোগ ও অন্যান্য স্থানীয় তথ্য যাচাই করে আপডেট করুন।</p><p class="page-lead">প্রয়োজনের সময় নির্ভরযোগ্য যোগাযোগের তথ্য সহজে পাওয়া গুরুত্বপূর্ণ। ভুল নম্বর বা পুরোনো তথ্য ক্ষতির কারণ হতে পারে, তাই প্রকাশের আগে প্রতিটি তথ্য যাচাই করুন।</p><section><h2>ডাক ও সরকারি সেবা</h2><p>সংশ্লিষ্ট ডাকঘরের নাম, ঠিকানা, খোলার সময় ও প্রকাশ্য যোগাযোগের তথ্য যোগ করুন।</p></section><section><h2>জরুরি যোগাযোগ</h2><p>পুলিশ, ফায়ার সার্ভিস, অ্যাম্বুলেন্স বা অন্যান্য প্রাসঙ্গিক সেবার সরকারি নম্বর ও স্থানীয় সেবার তথ্য যাচাই করে প্রকাশ করুন।</p></section><section><h2>তথ্য হালনাগাদ</h2><p>নতুন তথ্য, সংশোধন বা প্রাসঙ্গিক ছবি যোগ করতে এই পৃষ্ঠাটি ড্যাশবোর্ডের Page সেকশন থেকে সম্পাদনা করুন। নির্দিষ্ট তথ্যের উৎস ও সর্বশেষ হালনাগাদের তারিখ উল্লেখ করা ভালো।</p></section><style>.village-page-content{color:#263238;line-height:1.8;font-size:16px}.village-page-content .page-draft-note{padding:12px 14px;border-left:4px solid #b7791f;background:#fff8e6;border-radius:6px;font-size:14px}.village-page-content .page-lead{font-size:18px;color:#374151}.village-page-content section{margin:22px 0;padding:18px 20px;border:1px solid #e5e7eb;border-radius:12px;background:#fff}.village-page-content h2{margin:0 0 10px;color:#234e52;font-size:22px}.village-page-content p{margin:0 0 10px}.village-page-content p:last-child{margin-bottom:0}@media(max-width:600px){.village-page-content section{padding:14px}.village-page-content h2{font-size:19px}.village-page-content .page-lead{font-size:16px}}</style></div>','public','[]'::jsonb),
('দর্শনীয় স্থান','গ্রাম ও আশপাশের উল্লেখযোগ্য স্থান এবং দর্শনীয় জায়গা।','places','<div class="village-page-content"><p class="page-draft-note"><strong>সম্পাদনার নোট:</strong> এটি একটি প্রাথমিক ধারণাগত খসড়া। বাস্তব নাম, সংখ্যা, ঠিকানা, যোগাযোগ ও অন্যান্য স্থানীয় তথ্য যাচাই করে আপডেট করুন।</p><p class="page-lead">গ্রামের পরিচিত স্থান, ঐতিহাসিক নিদর্শন, প্রাকৃতিক দৃশ্য ও জনসাধারণের জন্য উন্মুক্ত জায়গার পরিচিতি এখানে তুলে ধরা হবে।</p><section><h2>স্থান পরিচিতি</h2><p>প্রতিটি স্থানের নাম, অবস্থান, গুরুত্ব, যাতায়াতের উপায় এবং প্রবেশের নিয়ম থাকলে তা লিখুন।</p></section><section><h2>দর্শনার্থীদের জন্য তথ্য</h2><p>খোলার সময়, অনুমতি, পরিচ্ছন্নতা ও পরিবেশ সংরক্ষণের নির্দেশনা কেবল যাচাইকৃত হলে যোগ করুন।</p></section><section><h2>তথ্য হালনাগাদ</h2><p>নতুন তথ্য, সংশোধন বা প্রাসঙ্গিক ছবি যোগ করতে এই পৃষ্ঠাটি ড্যাশবোর্ডের Page সেকশন থেকে সম্পাদনা করুন। নির্দিষ্ট তথ্যের উৎস ও সর্বশেষ হালনাগাদের তারিখ উল্লেখ করা ভালো।</p></section><style>.village-page-content{color:#263238;line-height:1.8;font-size:16px}.village-page-content .page-draft-note{padding:12px 14px;border-left:4px solid #b7791f;background:#fff8e6;border-radius:6px;font-size:14px}.village-page-content .page-lead{font-size:18px;color:#374151}.village-page-content section{margin:22px 0;padding:18px 20px;border:1px solid #e5e7eb;border-radius:12px;background:#fff}.village-page-content h2{margin:0 0 10px;color:#234e52;font-size:22px}.village-page-content p{margin:0 0 10px}.village-page-content p:last-child{margin-bottom:0}@media(max-width:600px){.village-page-content section{padding:14px}.village-page-content h2{font-size:19px}.village-page-content .page-lead{font-size:16px}}</style></div>','public','[]'::jsonb),
('সংস্কৃতি ও ঐতিহ্য','গ্রামের সাংস্কৃতিক চর্চা, লোকজ ঐতিহ্য, রীতি ও উৎসব।','culture','<div class="village-page-content"><p class="page-draft-note"><strong>সম্পাদনার নোট:</strong> এটি একটি প্রাথমিক ধারণাগত খসড়া। বাস্তব নাম, সংখ্যা, ঠিকানা, যোগাযোগ ও অন্যান্য স্থানীয় তথ্য যাচাই করে আপডেট করুন।</p><p class="page-lead">স্থানীয় সংস্কৃতি ও ঐতিহ্য গ্রামের পরিচয়ের গুরুত্বপূর্ণ অংশ। প্রবীণদের স্মৃতি, স্থানীয় নথি এবং সম্প্রদায়ের সম্মতিপ্রাপ্ত বিবরণ দিয়ে এই পৃষ্ঠা সমৃদ্ধ করা যেতে পারে।</p><section><h2>লোকজ ঐতিহ্য</h2><p>প্রচলিত রীতি, লোকগান, লোককথা, হস্তশিল্প, খাবার বা সাংস্কৃতিক চর্চার তথ্য যাচাই করে লিখুন।</p></section><section><h2>সংরক্ষণ</h2><p>ছবি, অডিও বা স্মৃতিচারণ প্রকাশের আগে সংশ্লিষ্ট ব্যক্তির সম্মতি নিন এবং তথ্যের উৎস উল্লেখ করুন।</p></section><section><h2>তথ্য হালনাগাদ</h2><p>নতুন তথ্য, সংশোধন বা প্রাসঙ্গিক ছবি যোগ করতে এই পৃষ্ঠাটি ড্যাশবোর্ডের Page সেকশন থেকে সম্পাদনা করুন। নির্দিষ্ট তথ্যের উৎস ও সর্বশেষ হালনাগাদের তারিখ উল্লেখ করা ভালো।</p></section><style>.village-page-content{color:#263238;line-height:1.8;font-size:16px}.village-page-content .page-draft-note{padding:12px 14px;border-left:4px solid #b7791f;background:#fff8e6;border-radius:6px;font-size:14px}.village-page-content .page-lead{font-size:18px;color:#374151}.village-page-content section{margin:22px 0;padding:18px 20px;border:1px solid #e5e7eb;border-radius:12px;background:#fff}.village-page-content h2{margin:0 0 10px;color:#234e52;font-size:22px}.village-page-content p{margin:0 0 10px}.village-page-content p:last-child{margin-bottom:0}@media(max-width:600px){.village-page-content section{padding:14px}.village-page-content h2{font-size:19px}.village-page-content .page-lead{font-size:16px}}</style></div>','public','[]'::jsonb),
('নদী ও প্রাকৃতিক সৌন্দর্য','গ্রামের নদী, খাল, জলাশয়, মাঠ, গাছপালা ও প্রাকৃতিক পরিবেশ।','nature','<div class="village-page-content"><p class="page-draft-note"><strong>সম্পাদনার নোট:</strong> এটি একটি প্রাথমিক ধারণাগত খসড়া। বাস্তব নাম, সংখ্যা, ঠিকানা, যোগাযোগ ও অন্যান্য স্থানীয় তথ্য যাচাই করে আপডেট করুন।</p><p class="page-lead">প্রাকৃতিক পরিবেশ গ্রামের জীবনযাত্রা ও জীববৈচিত্র্যের সঙ্গে সম্পর্কিত। এই পৃষ্ঠায় স্থানীয় জলাশয়, সবুজ এলাকা ও পরিবেশগত পরিবর্তন সম্পর্কে যাচাইকৃত তথ্য তুলে ধরা হবে।</p><section><h2>প্রাকৃতিক স্থান</h2><p>নদী, খাল, পুকুর, মাঠ, বৃক্ষরাজি বা অন্যান্য প্রাকৃতিক স্থানের নাম ও অবস্থান যোগ করুন।</p></section><section><h2>পরিবেশ সংরক্ষণ</h2><p>পানি, বর্জ্য, বৃক্ষরোপণ ও স্থানীয় জীববৈচিত্র্য রক্ষায় প্রাসঙ্গিক উদ্যোগ এবং যাচাইকৃত তথ্য উল্লেখ করুন।</p></section><section><h2>তথ্য হালনাগাদ</h2><p>নতুন তথ্য, সংশোধন বা প্রাসঙ্গিক ছবি যোগ করতে এই পৃষ্ঠাটি ড্যাশবোর্ডের Page সেকশন থেকে সম্পাদনা করুন। নির্দিষ্ট তথ্যের উৎস ও সর্বশেষ হালনাগাদের তারিখ উল্লেখ করা ভালো।</p></section><style>.village-page-content{color:#263238;line-height:1.8;font-size:16px}.village-page-content .page-draft-note{padding:12px 14px;border-left:4px solid #b7791f;background:#fff8e6;border-radius:6px;font-size:14px}.village-page-content .page-lead{font-size:18px;color:#374151}.village-page-content section{margin:22px 0;padding:18px 20px;border:1px solid #e5e7eb;border-radius:12px;background:#fff}.village-page-content h2{margin:0 0 10px;color:#234e52;font-size:22px}.village-page-content p{margin:0 0 10px}.village-page-content p:last-child{margin-bottom:0}@media(max-width:600px){.village-page-content section{padding:14px}.village-page-content h2{font-size:19px}.village-page-content .page-lead{font-size:16px}}</style></div>','public','[]'::jsonb),
('ছবি ও গ্যালারি','গ্রামের জীবন, প্রকৃতি, অনুষ্ঠান ও স্থানের ছবির সংগ্রহ।','gallery','<div class="village-page-content"><p class="page-draft-note"><strong>সম্পাদনার নোট:</strong> এটি একটি প্রাথমিক ধারণাগত খসড়া। বাস্তব নাম, সংখ্যা, ঠিকানা, যোগাযোগ ও অন্যান্য স্থানীয় তথ্য যাচাই করে আপডেট করুন।</p><p class="page-lead">ছবি গ্রামের দৃশ্য, মানুষ, ঐতিহ্য ও সময়ের পরিবর্তন সংরক্ষণে সাহায্য করে। প্রতিটি ছবির সঙ্গে প্রাসঙ্গিক শিরোনাম, স্থান, তারিখ এবং অনুমতি-সংক্রান্ত তথ্য যোগ করুন।</p><section><h2>ছবি সাজানোর নিয়ম</h2><p>ছবিগুলো স্থান, অনুষ্ঠান, প্রকৃতি বা সময় অনুযায়ী সাজানো যেতে পারে। ছবির ক্যাপশন যেন দৃশ্যের সঙ্গে মিলে তা নিশ্চিত করুন।</p></section><section><h2>গোপনীয়তা ও অধিকার</h2><p>ব্যক্তির ছবি প্রকাশের আগে প্রয়োজনীয় সম্মতি নিন এবং অন্যের তোলা ছবি ব্যবহারের অধিকার যাচাই করুন।</p></section><section><h2>তথ্য হালনাগাদ</h2><p>নতুন তথ্য, সংশোধন বা প্রাসঙ্গিক ছবি যোগ করতে এই পৃষ্ঠাটি ড্যাশবোর্ডের Page সেকশন থেকে সম্পাদনা করুন। নির্দিষ্ট তথ্যের উৎস ও সর্বশেষ হালনাগাদের তারিখ উল্লেখ করা ভালো।</p></section><style>.village-page-content{color:#263238;line-height:1.8;font-size:16px}.village-page-content .page-draft-note{padding:12px 14px;border-left:4px solid #b7791f;background:#fff8e6;border-radius:6px;font-size:14px}.village-page-content .page-lead{font-size:18px;color:#374151}.village-page-content section{margin:22px 0;padding:18px 20px;border:1px solid #e5e7eb;border-radius:12px;background:#fff}.village-page-content h2{margin:0 0 10px;color:#234e52;font-size:22px}.village-page-content p{margin:0 0 10px}.village-page-content p:last-child{margin-bottom:0}@media(max-width:600px){.village-page-content section{padding:14px}.village-page-content h2{font-size:19px}.village-page-content .page-lead{font-size:16px}}</style></div>','public','[]'::jsonb),
('অনুষ্ঠান ও উৎসব','গ্রামের অনুষ্ঠান, মেলা, উৎসব ও কমিউনিটি কার্যক্রমের তথ্য।','events','<div class="village-page-content"><p class="page-draft-note"><strong>সম্পাদনার নোট:</strong> এটি একটি প্রাথমিক ধারণাগত খসড়া। বাস্তব নাম, সংখ্যা, ঠিকানা, যোগাযোগ ও অন্যান্য স্থানীয় তথ্য যাচাই করে আপডেট করুন।</p><p class="page-lead">স্থানীয় অনুষ্ঠান ও উৎসবের তথ্য গ্রামবাসীকে একত্রিত করতে এবং ঐতিহ্য সংরক্ষণে সহায়ক। তারিখ, স্থান ও আয়োজনকারীর তথ্য নিশ্চিত হওয়ার পর প্রকাশ করুন।</p><section><h2>আসন্ন আয়োজন</h2><p>অনুষ্ঠানের নাম, তারিখ, সময়, স্থান, আয়োজক এবং অংশগ্রহণের নিয়ম যাচাই করে উল্লেখ করুন।</p></section><section><h2>পূর্ববর্তী অনুষ্ঠান</h2><p>অনুষ্ঠানের সংক্ষিপ্ত বিবরণ ও ছবি প্রকাশের আগে তথ্য এবং ছবি ব্যবহারের অনুমতি যাচাই করুন।</p></section><section><h2>তথ্য হালনাগাদ</h2><p>নতুন তথ্য, সংশোধন বা প্রাসঙ্গিক ছবি যোগ করতে এই পৃষ্ঠাটি ড্যাশবোর্ডের Page সেকশন থেকে সম্পাদনা করুন। নির্দিষ্ট তথ্যের উৎস ও সর্বশেষ হালনাগাদের তারিখ উল্লেখ করা ভালো।</p></section><style>.village-page-content{color:#263238;line-height:1.8;font-size:16px}.village-page-content .page-draft-note{padding:12px 14px;border-left:4px solid #b7791f;background:#fff8e6;border-radius:6px;font-size:14px}.village-page-content .page-lead{font-size:18px;color:#374151}.village-page-content section{margin:22px 0;padding:18px 20px;border:1px solid #e5e7eb;border-radius:12px;background:#fff}.village-page-content h2{margin:0 0 10px;color:#234e52;font-size:22px}.village-page-content p{margin:0 0 10px}.village-page-content p:last-child{margin-bottom:0}@media(max-width:600px){.village-page-content section{padding:14px}.village-page-content h2{font-size:19px}.village-page-content .page-lead{font-size:16px}}</style></div>','public','[]'::jsonb),
('গ্রামের খেলাধুলা','স্থানীয় খেলাধুলা, মাঠ, দল, প্রতিযোগিতা ও ক্রীড়া কার্যক্রম।','sports','<div class="village-page-content"><p class="page-draft-note"><strong>সম্পাদনার নোট:</strong> এটি একটি প্রাথমিক ধারণাগত খসড়া। বাস্তব নাম, সংখ্যা, ঠিকানা, যোগাযোগ ও অন্যান্য স্থানীয় তথ্য যাচাই করে আপডেট করুন।</p><p class="page-lead">খেলাধুলা গ্রামের তরুণদের অংশগ্রহণ, সুস্থতা ও সামাজিক বন্ধন বাড়াতে ভূমিকা রাখতে পারে। স্থানীয়ভাবে প্রচলিত খেলা এবং যাচাইকৃত ক্রীড়া কার্যক্রমের তথ্য এখানে যোগ করুন।</p><section><h2>খেলা ও মাঠ</h2><p>খেলার ধরন, মাঠের অবস্থান, স্থানীয় দল বা ক্লাবের নাম এবং ব্যবহারের নিয়ম থাকলে লিখুন।</p></section><section><h2>প্রতিযোগিতা</h2><p>টুর্নামেন্টের সময়সূচি, আয়োজক ও ফলাফল নিশ্চিত হওয়ার পর প্রকাশ করুন।</p></section><section><h2>তথ্য হালনাগাদ</h2><p>নতুন তথ্য, সংশোধন বা প্রাসঙ্গিক ছবি যোগ করতে এই পৃষ্ঠাটি ড্যাশবোর্ডের Page সেকশন থেকে সম্পাদনা করুন। নির্দিষ্ট তথ্যের উৎস ও সর্বশেষ হালনাগাদের তারিখ উল্লেখ করা ভালো।</p></section><style>.village-page-content{color:#263238;line-height:1.8;font-size:16px}.village-page-content .page-draft-note{padding:12px 14px;border-left:4px solid #b7791f;background:#fff8e6;border-radius:6px;font-size:14px}.village-page-content .page-lead{font-size:18px;color:#374151}.village-page-content section{margin:22px 0;padding:18px 20px;border:1px solid #e5e7eb;border-radius:12px;background:#fff}.village-page-content h2{margin:0 0 10px;color:#234e52;font-size:22px}.village-page-content p{margin:0 0 10px}.village-page-content p:last-child{margin-bottom:0}@media(max-width:600px){.village-page-content section{padding:14px}.village-page-content h2{font-size:19px}.village-page-content .page-lead{font-size:16px}}</style></div>','public','[]'::jsonb),
('গ্রামের ইতিহাস ও স্মৃতিচারণ','প্রবীণদের স্মৃতি, পুরোনো ছবি ও ব্যক্তিগত অভিজ্ঞতার সংরক্ষণ।','memories','<div class="village-page-content"><p class="page-draft-note"><strong>সম্পাদনার নোট:</strong> এটি একটি প্রাথমিক ধারণাগত খসড়া। বাস্তব নাম, সংখ্যা, ঠিকানা, যোগাযোগ ও অন্যান্য স্থানীয় তথ্য যাচাই করে আপডেট করুন।</p><p class="page-lead">ব্যক্তিগত স্মৃতিচারণ গ্রামের সামাজিক ইতিহাসের মূল্যবান অংশ হতে পারে। স্মৃতিগুলোকে ব্যক্তিগত অভিজ্ঞতা হিসেবে উপস্থাপন করুন এবং যাচাইযোগ্য ঐতিহাসিক দাবির সঙ্গে পার্থক্য স্পষ্ট রাখুন।</p><section><h2>স্মৃতিচারণ</h2><p>লেখকের নাম বা অনুমোদিত পরিচয়, স্মৃতির সময়কাল এবং ঘটনার প্রেক্ষাপট যোগ করুন।</p></section><section><h2>পুরোনো ছবি ও নথি</h2><p>ছবির আনুমানিক সাল, স্থান, পরিচিত ব্যক্তিদের নাম (সম্মতি ও যাচাই সাপেক্ষে) এবং ছবির উৎস উল্লেখ করুন।</p></section><section><h2>তথ্য হালনাগাদ</h2><p>নতুন তথ্য, সংশোধন বা প্রাসঙ্গিক ছবি যোগ করতে এই পৃষ্ঠাটি ড্যাশবোর্ডের Page সেকশন থেকে সম্পাদনা করুন। নির্দিষ্ট তথ্যের উৎস ও সর্বশেষ হালনাগাদের তারিখ উল্লেখ করা ভালো।</p></section><style>.village-page-content{color:#263238;line-height:1.8;font-size:16px}.village-page-content .page-draft-note{padding:12px 14px;border-left:4px solid #b7791f;background:#fff8e6;border-radius:6px;font-size:14px}.village-page-content .page-lead{font-size:18px;color:#374151}.village-page-content section{margin:22px 0;padding:18px 20px;border:1px solid #e5e7eb;border-radius:12px;background:#fff}.village-page-content h2{margin:0 0 10px;color:#234e52;font-size:22px}.village-page-content p{margin:0 0 10px}.village-page-content p:last-child{margin-bottom:0}@media(max-width:600px){.village-page-content section{padding:14px}.village-page-content h2{font-size:19px}.village-page-content .page-lead{font-size:16px}}</style></div>','public','[]'::jsonb),
('গ্রামের উন্নয়ন কার্যক্রম','চলমান ও সম্পন্ন উন্নয়ন প্রকল্প, অবকাঠামো ও জনকল্যাণমূলক উদ্যোগ।','development','<div class="village-page-content"><p class="page-draft-note"><strong>সম্পাদনার নোট:</strong> এটি একটি প্রাথমিক ধারণাগত খসড়া। বাস্তব নাম, সংখ্যা, ঠিকানা, যোগাযোগ ও অন্যান্য স্থানীয় তথ্য যাচাই করে আপডেট করুন।</p><p class="page-lead">উন্নয়ন কার্যক্রমের নিরপেক্ষ ও হালনাগাদ তথ্য বাসিন্দাদের অবগত থাকতে সাহায্য করে। প্রকল্পের অবস্থা, অর্থায়ন ও দায়িত্বপ্রাপ্ত সংস্থার তথ্য নির্ভরযোগ্য উৎস থেকে যাচাই করুন।</p><section><h2>প্রকল্পের বিবরণ</h2><p>প্রকল্পের নাম, স্থান, দায়িত্বপ্রাপ্ত সংস্থা, ঘোষিত সময়সীমা ও প্রকাশ্য নথির লিংক যোগ করুন।</p></section><section><h2>অগ্রগতি</h2><p>প্রস্তাবিত, চলমান বা সম্পন্ন—অবস্থা স্পষ্টভাবে লিখুন এবং সর্বশেষ হালনাগাদের তারিখ উল্লেখ করুন।</p></section><section><h2>তথ্য হালনাগাদ</h2><p>নতুন তথ্য, সংশোধন বা প্রাসঙ্গিক ছবি যোগ করতে এই পৃষ্ঠাটি ড্যাশবোর্ডের Page সেকশন থেকে সম্পাদনা করুন। নির্দিষ্ট তথ্যের উৎস ও সর্বশেষ হালনাগাদের তারিখ উল্লেখ করা ভালো।</p></section><style>.village-page-content{color:#263238;line-height:1.8;font-size:16px}.village-page-content .page-draft-note{padding:12px 14px;border-left:4px solid #b7791f;background:#fff8e6;border-radius:6px;font-size:14px}.village-page-content .page-lead{font-size:18px;color:#374151}.village-page-content section{margin:22px 0;padding:18px 20px;border:1px solid #e5e7eb;border-radius:12px;background:#fff}.village-page-content h2{margin:0 0 10px;color:#234e52;font-size:22px}.village-page-content p{margin:0 0 10px}.village-page-content p:last-child{margin-bottom:0}@media(max-width:600px){.village-page-content section{padding:14px}.village-page-content h2{font-size:19px}.village-page-content .page-lead{font-size:16px}}</style></div>','public','[]'::jsonb),
('স্থানীয় সংবাদ','গ্রামের প্রাসঙ্গিক সংবাদ, ঘোষণা ও জনস্বার্থমূলক তথ্য।','local-news','<div class="village-page-content"><p class="page-draft-note"><strong>সম্পাদনার নোট:</strong> এটি একটি প্রাথমিক ধারণাগত খসড়া। বাস্তব নাম, সংখ্যা, ঠিকানা, যোগাযোগ ও অন্যান্য স্থানীয় তথ্য যাচাই করে আপডেট করুন।</p><p class="page-lead">এই পৃষ্ঠায় গ্রামের মানুষের জন্য প্রাসঙ্গিক ও যাচাই করা সংবাদ প্রকাশ করা হবে। তথ্যের উৎস যাচাই, নিরপেক্ষ ভাষা এবং সংশোধনের স্বচ্ছতা বজায় রাখুন।</p><section><h2>সংবাদ প্রকাশ</h2><p>শিরোনাম, প্রকাশের তারিখ, ঘটনার স্থান, নির্ভরযোগ্য সূত্র এবং প্রয়োজনীয় প্রেক্ষাপট যোগ করুন।</p></section><section><h2>যাচাই ও সংশোধন</h2><p>অপ্রমাণিত অভিযোগ বা গুজব প্রকাশ করবেন না। ভুল পাওয়া গেলে দ্রুত সংশোধন করে সংশোধনের তারিখ উল্লেখ করুন।</p></section><section><h2>তথ্য হালনাগাদ</h2><p>নতুন তথ্য, সংশোধন বা প্রাসঙ্গিক ছবি যোগ করতে এই পৃষ্ঠাটি ড্যাশবোর্ডের Page সেকশন থেকে সম্পাদনা করুন। নির্দিষ্ট তথ্যের উৎস ও সর্বশেষ হালনাগাদের তারিখ উল্লেখ করা ভালো।</p></section><style>.village-page-content{color:#263238;line-height:1.8;font-size:16px}.village-page-content .page-draft-note{padding:12px 14px;border-left:4px solid #b7791f;background:#fff8e6;border-radius:6px;font-size:14px}.village-page-content .page-lead{font-size:18px;color:#374151}.village-page-content section{margin:22px 0;padding:18px 20px;border:1px solid #e5e7eb;border-radius:12px;background:#fff}.village-page-content h2{margin:0 0 10px;color:#234e52;font-size:22px}.village-page-content p{margin:0 0 10px}.village-page-content p:last-child{margin-bottom:0}@media(max-width:600px){.village-page-content section{padding:14px}.village-page-content h2{font-size:19px}.village-page-content .page-lead{font-size:16px}}</style></div>','public','[]'::jsonb),
('জন্ম ও মৃত্যু সংবাদ','পরিবারের সম্মতি নিয়ে জন্ম, মৃত্যু ও স্মরণসংক্রান্ত ঘোষণা।','births-deaths','<div class="village-page-content"><p class="page-draft-note"><strong>সম্পাদনার নোট:</strong> এটি একটি প্রাথমিক ধারণাগত খসড়া। বাস্তব নাম, সংখ্যা, ঠিকানা, যোগাযোগ ও অন্যান্য স্থানীয় তথ্য যাচাই করে আপডেট করুন।</p><p class="page-lead">জন্ম ও মৃত্যু সংবাদ সংবেদনশীল পারিবারিক তথ্য। এই পৃষ্ঠা ব্যবহারের আগে পরিবারের স্পষ্ট সম্মতি নিন এবং কেবল প্রকাশের জন্য অনুমোদিত তথ্য দিন।</p><section><h2>জন্মসংবাদ</h2><p>পরিবারের অনুমতি অনুযায়ী শিশুর নাম (যদি প্রকাশযোগ্য হয়), জন্মতারিখ এবং সংক্ষিপ্ত শুভেচ্ছা যোগ করা যেতে পারে।</p></section><section><h2>মৃত্যু ও স্মরণ</h2><p>পরিবারের অনুমতি নিয়ে নাম, তারিখ, জানাজা/শেষকৃত্যের প্রকাশযোগ্য তথ্য এবং স্মরণবার্তা দিন। ব্যক্তিগত তথ্য সীমিত রাখুন।</p></section><section><h2>তথ্য হালনাগাদ</h2><p>নতুন তথ্য, সংশোধন বা প্রাসঙ্গিক ছবি যোগ করতে এই পৃষ্ঠাটি ড্যাশবোর্ডের Page সেকশন থেকে সম্পাদনা করুন। নির্দিষ্ট তথ্যের উৎস ও সর্বশেষ হালনাগাদের তারিখ উল্লেখ করা ভালো।</p></section><style>.village-page-content{color:#263238;line-height:1.8;font-size:16px}.village-page-content .page-draft-note{padding:12px 14px;border-left:4px solid #b7791f;background:#fff8e6;border-radius:6px;font-size:14px}.village-page-content .page-lead{font-size:18px;color:#374151}.village-page-content section{margin:22px 0;padding:18px 20px;border:1px solid #e5e7eb;border-radius:12px;background:#fff}.village-page-content h2{margin:0 0 10px;color:#234e52;font-size:22px}.village-page-content p{margin:0 0 10px}.village-page-content p:last-child{margin-bottom:0}@media(max-width:600px){.village-page-content section{padding:14px}.village-page-content h2{font-size:19px}.village-page-content .page-lead{font-size:16px}}</style></div>','public','[]'::jsonb),
('চাকরি ও কর্মসংস্থান','যাচাইকৃত চাকরির বিজ্ঞপ্তি, প্রশিক্ষণ ও কর্মসংস্থানের সুযোগ।','jobs','<div class="village-page-content"><p class="page-draft-note"><strong>সম্পাদনার নোট:</strong> এটি একটি প্রাথমিক ধারণাগত খসড়া। বাস্তব নাম, সংখ্যা, ঠিকানা, যোগাযোগ ও অন্যান্য স্থানীয় তথ্য যাচাই করে আপডেট করুন।</p><p class="page-lead">স্থানীয় চাকরি ও প্রশিক্ষণের তথ্য কর্মপ্রত্যাশীদের উপকার করতে পারে। বিজ্ঞপ্তির উৎস, আবেদনের শেষ তারিখ এবং যোগ্যতা যাচাই করে প্রকাশ করুন।</p><section><h2>সুযোগের বিবরণ</h2><p>পদের নাম, নিয়োগকারী প্রতিষ্ঠান, যোগ্যতা, কর্মস্থল, আবেদনের নিয়ম এবং শেষ তারিখ উল্লেখ করুন।</p></section><section><h2>প্রতারণা থেকে সতর্কতা</h2><p>যাচাই ছাড়া চাকরির বিজ্ঞপ্তি প্রকাশ করবেন না। আবেদন বা নিয়োগের নামে টাকা চাওয়া হলে সতর্কবার্তা দিন এবং উৎস যাচাই করুন।</p></section><section><h2>তথ্য হালনাগাদ</h2><p>নতুন তথ্য, সংশোধন বা প্রাসঙ্গিক ছবি যোগ করতে এই পৃষ্ঠাটি ড্যাশবোর্ডের Page সেকশন থেকে সম্পাদনা করুন। নির্দিষ্ট তথ্যের উৎস ও সর্বশেষ হালনাগাদের তারিখ উল্লেখ করা ভালো।</p></section><style>.village-page-content{color:#263238;line-height:1.8;font-size:16px}.village-page-content .page-draft-note{padding:12px 14px;border-left:4px solid #b7791f;background:#fff8e6;border-radius:6px;font-size:14px}.village-page-content .page-lead{font-size:18px;color:#374151}.village-page-content section{margin:22px 0;padding:18px 20px;border:1px solid #e5e7eb;border-radius:12px;background:#fff}.village-page-content h2{margin:0 0 10px;color:#234e52;font-size:22px}.village-page-content p{margin:0 0 10px}.village-page-content p:last-child{margin-bottom:0}@media(max-width:600px){.village-page-content section{padding:14px}.village-page-content h2{font-size:19px}.village-page-content .page-lead{font-size:16px}}</style></div>','public','[]'::jsonb),
('প্রবাসী গ্রামবাসী','প্রবাসে থাকা গ্রামবাসীদের অভিজ্ঞতা, অবদান ও যোগাযোগের উদ্যোগ।','expatriates','<div class="village-page-content"><p class="page-draft-note"><strong>সম্পাদনার নোট:</strong> এটি একটি প্রাথমিক ধারণাগত খসড়া। বাস্তব নাম, সংখ্যা, ঠিকানা, যোগাযোগ ও অন্যান্য স্থানীয় তথ্য যাচাই করে আপডেট করুন।</p><p class="page-lead">প্রবাসী গ্রামবাসীরা পরিবার, সমাজ ও স্থানীয় উন্নয়নের সঙ্গে নানা উপায়ে যুক্ত থাকেন। তাঁদের পরিচিতি বা অবদানের তথ্য প্রকাশের আগে স্পষ্ট সম্মতি নিন।</p><section><h2>পরিচিতি ও অভিজ্ঞতা</h2><p>প্রকাশে সম্মত ব্যক্তির সংক্ষিপ্ত পরিচয়, বসবাসের দেশ (ইচ্ছা ও সম্মতি অনুযায়ী) এবং অভিজ্ঞতা তুলে ধরুন।</p></section><section><h2>সম্পৃক্ততা</h2><p>সামাজিক উদ্যোগ বা গ্রামের সঙ্গে যোগাযোগের কার্যক্রমের তথ্য যাচাই করে প্রকাশ করুন। ব্যক্তিগত ঠিকানা ও নম্বর অনুমতি ছাড়া দেবেন না।</p></section><section><h2>তথ্য হালনাগাদ</h2><p>নতুন তথ্য, সংশোধন বা প্রাসঙ্গিক ছবি যোগ করতে এই পৃষ্ঠাটি ড্যাশবোর্ডের Page সেকশন থেকে সম্পাদনা করুন। নির্দিষ্ট তথ্যের উৎস ও সর্বশেষ হালনাগাদের তারিখ উল্লেখ করা ভালো।</p></section><style>.village-page-content{color:#263238;line-height:1.8;font-size:16px}.village-page-content .page-draft-note{padding:12px 14px;border-left:4px solid #b7791f;background:#fff8e6;border-radius:6px;font-size:14px}.village-page-content .page-lead{font-size:18px;color:#374151}.village-page-content section{margin:22px 0;padding:18px 20px;border:1px solid #e5e7eb;border-radius:12px;background:#fff}.village-page-content h2{margin:0 0 10px;color:#234e52;font-size:22px}.village-page-content p{margin:0 0 10px}.village-page-content p:last-child{margin-bottom:0}@media(max-width:600px){.village-page-content section{padding:14px}.village-page-content h2{font-size:19px}.village-page-content .page-lead{font-size:16px}}</style></div>','public','[]'::jsonb),
('যোগাযোগ ও যাতায়াতের রুট','বিভিন্ন স্থান থেকে গ্রামের পথে আসার নির্দেশনা ও রুট-তথ্য।','routes','<div class="village-page-content"><p class="page-draft-note"><strong>সম্পাদনার নোট:</strong> এটি একটি প্রাথমিক ধারণাগত খসড়া। বাস্তব নাম, সংখ্যা, ঠিকানা, যোগাযোগ ও অন্যান্য স্থানীয় তথ্য যাচাই করে আপডেট করুন।</p><p class="page-lead">গ্রামে পৌঁছানোর পথ সহজে বুঝতে রুটের বর্ণনা, পরিচিত মোড় এবং পরিবহনকেন্দ্রের তথ্য উপকারী। দূরত্ব ও ভ্রমণসময় আনুমানিক হলে তা স্পষ্ট করে লিখুন।</p><section><h2>প্রধান রুট</h2><p>শুরুর স্থান, প্রধান সড়ক, মোড়, সংযোগস্থল এবং গ্রামের প্রবেশপথ ধাপে ধাপে লিখুন।</p></section><section><h2>দূরত্ব ও সময়</h2><p>মানচিত্র বা বাস্তব যাত্রা দিয়ে দূরত্ব যাচাই করুন। যানজট, আবহাওয়া ও পরিবহনভেদে সময় পরিবর্তিত হতে পারে—এ কথা উল্লেখ করুন।</p></section><section><h2>তথ্য হালনাগাদ</h2><p>নতুন তথ্য, সংশোধন বা প্রাসঙ্গিক ছবি যোগ করতে এই পৃষ্ঠাটি ড্যাশবোর্ডের Page সেকশন থেকে সম্পাদনা করুন। নির্দিষ্ট তথ্যের উৎস ও সর্বশেষ হালনাগাদের তারিখ উল্লেখ করা ভালো।</p></section><style>.village-page-content{color:#263238;line-height:1.8;font-size:16px}.village-page-content .page-draft-note{padding:12px 14px;border-left:4px solid #b7791f;background:#fff8e6;border-radius:6px;font-size:14px}.village-page-content .page-lead{font-size:18px;color:#374151}.village-page-content section{margin:22px 0;padding:18px 20px;border:1px solid #e5e7eb;border-radius:12px;background:#fff}.village-page-content h2{margin:0 0 10px;color:#234e52;font-size:22px}.village-page-content p{margin:0 0 10px}.village-page-content p:last-child{margin-bottom:0}@media(max-width:600px){.village-page-content section{padding:14px}.village-page-content h2{font-size:19px}.village-page-content .page-lead{font-size:16px}}</style></div>','public','[]'::jsonb),
('About','Dalimgari ওয়েবসাইটের উদ্দেশ্য, পরিধি ও তথ্য প্রকাশের নীতি।','about','<div class="village-page-content"><p class="page-draft-note"><strong>সম্পাদনার নোট:</strong> এটি একটি প্রাথমিক ধারণাগত খসড়া। বাস্তব নাম, সংখ্যা, ঠিকানা, যোগাযোগ ও অন্যান্য স্থানীয় তথ্য যাচাই করে আপডেট করুন।</p><p class="page-lead">Dalimgari হলো ডালিমগাড়ী গ্রাম সম্পর্কিত পরিচিতি, ইতিহাস, স্থানীয় প্রতিষ্ঠান, সংস্কৃতি ও প্রয়োজনীয় তথ্য এক জায়গায় সাজিয়ে রাখার একটি ওয়েবসাইট।</p><section><h2>আমাদের উদ্দেশ্য</h2><p>গ্রামের তথ্য সহজে খুঁজে পাওয়া, স্থানীয় ইতিহাস ও স্মৃতি সংরক্ষণ এবং যাচাই করা তথ্য মানুষের কাছে পৌঁছে দেওয়াই এই ওয়েবসাইটের লক্ষ্য।</p></section><section><h2>তথ্যের মান</h2><p>তথ্য সময়ের সঙ্গে বদলাতে পারে। ভুল বা পুরোনো তথ্য চোখে পড়লে যোগাযোগের মাধ্যমে জানালে যাচাই করে সংশোধন করা হবে।</p></section><section><h2>তথ্য হালনাগাদ</h2><p>নতুন তথ্য, সংশোধন বা প্রাসঙ্গিক ছবি যোগ করতে এই পৃষ্ঠাটি ড্যাশবোর্ডের Page সেকশন থেকে সম্পাদনা করুন। নির্দিষ্ট তথ্যের উৎস ও সর্বশেষ হালনাগাদের তারিখ উল্লেখ করা ভালো।</p></section><style>.village-page-content{color:#263238;line-height:1.8;font-size:16px}.village-page-content .page-draft-note{padding:12px 14px;border-left:4px solid #b7791f;background:#fff8e6;border-radius:6px;font-size:14px}.village-page-content .page-lead{font-size:18px;color:#374151}.village-page-content section{margin:22px 0;padding:18px 20px;border:1px solid #e5e7eb;border-radius:12px;background:#fff}.village-page-content h2{margin:0 0 10px;color:#234e52;font-size:22px}.village-page-content p{margin:0 0 10px}.village-page-content p:last-child{margin-bottom:0}@media(max-width:600px){.village-page-content section{padding:14px}.village-page-content h2{font-size:19px}.village-page-content .page-lead{font-size:16px}}</style></div>','public','[]'::jsonb),
('Contact','ওয়েবসাইটের তথ্য সংশোধন, অবদান বা সাধারণ যোগাযোগের উপায়।','contact','<div class="village-page-content"><p class="page-draft-note"><strong>সম্পাদনার নোট:</strong> এটি একটি প্রাথমিক ধারণাগত খসড়া। বাস্তব নাম, সংখ্যা, ঠিকানা, যোগাযোগ ও অন্যান্য স্থানীয় তথ্য যাচাই করে আপডেট করুন।</p><p class="page-lead">গ্রাম সম্পর্কিত তথ্য যোগ করা, ভুল সংশোধন, ছবি জমা দেওয়া বা ওয়েবসাইট সম্পর্কে প্রশ্ন জানাতে এই পৃষ্ঠা ব্যবহার করুন।</p><section><h2>কীভাবে যোগাযোগ করবেন</h2><p>প্রকাশের জন্য নির্ধারিত ইমেইল, যোগাযোগ ফর্ম বা অন্য অনুমোদিত মাধ্যম এখানে যোগ করুন। যোগাযোগের তথ্য নিশ্চিত না হওয়া পর্যন্ত নমুনা বা ভুয়া ঠিকানা প্রকাশ করবেন না।</p></section><section><h2>তথ্য পাঠানোর সময়</h2><p>তথ্যের উৎস, স্থান, তারিখ এবং প্রয়োজনে ছবি ব্যবহারের অনুমতি উল্লেখ করুন। ব্যক্তিগত বা সংবেদনশীল তথ্য পাঠানোর আগে তা প্রকাশযোগ্য কি না নিশ্চিত করুন।</p></section><section><h2>তথ্য হালনাগাদ</h2><p>নতুন তথ্য, সংশোধন বা প্রাসঙ্গিক ছবি যোগ করতে এই পৃষ্ঠাটি ড্যাশবোর্ডের Page সেকশন থেকে সম্পাদনা করুন। নির্দিষ্ট তথ্যের উৎস ও সর্বশেষ হালনাগাদের তারিখ উল্লেখ করা ভালো।</p></section><style>.village-page-content{color:#263238;line-height:1.8;font-size:16px}.village-page-content .page-draft-note{padding:12px 14px;border-left:4px solid #b7791f;background:#fff8e6;border-radius:6px;font-size:14px}.village-page-content .page-lead{font-size:18px;color:#374151}.village-page-content section{margin:22px 0;padding:18px 20px;border:1px solid #e5e7eb;border-radius:12px;background:#fff}.village-page-content h2{margin:0 0 10px;color:#234e52;font-size:22px}.village-page-content p{margin:0 0 10px}.village-page-content p:last-child{margin-bottom:0}@media(max-width:600px){.village-page-content section{padding:14px}.village-page-content h2{font-size:19px}.village-page-content .page-lead{font-size:16px}}</style></div>','public','[]'::jsonb),
('Privacy Policy','ওয়েবসাইট ব্যবহারকারীর তথ্য, গোপনীয়তা ও তথ্য ব্যবস্থাপনা সম্পর্কে খসড়া নীতি।','privacy-policy','<div class="village-page-content"><p class="page-draft-note"><strong>সম্পাদনার নোট:</strong> এটি একটি প্রাথমিক ধারণাগত খসড়া। বাস্তব নাম, সংখ্যা, ঠিকানা, যোগাযোগ ও অন্যান্য স্থানীয় তথ্য যাচাই করে আপডেট করুন।</p><p class="page-lead">এই পৃষ্ঠাটি গোপনীয়তা নীতির একটি প্রাথমিক খসড়া। ওয়েবসাইটে বাস্তবে কোন তথ্য সংগ্রহ করা হয়, কোন সেবা ব্যবহার করা হয় এবং তথ্য কত দিন রাখা হয়—সেগুলোর সঙ্গে মিলিয়ে প্রকাশের আগে সংশোধন করুন।</p><section><h2>তথ্য সংগ্রহ ও ব্যবহার</h2><p>ওয়েবসাইটে লগইন, যোগাযোগ বা ফাইল জমা দেওয়ার সময় যে তথ্য বাস্তবে সংগ্রহ করা হয়, তার ধরন ও ব্যবহারের উদ্দেশ্য নির্দিষ্টভাবে লিখুন। যে তথ্য সংগ্রহ করা হয় না, তা সংগ্রহ করা হয় বলে দাবি করবেন না।</p></section><section><h2>নিরাপত্তা ও যোগাযোগ</h2><p>তথ্য সংরক্ষণ, তৃতীয় পক্ষের সেবা, ব্যবহারকারীর অনুরোধ এবং গোপনীয়তা-সংক্রান্ত যোগাযোগের পদ্ধতি বাস্তব ব্যবস্থার ভিত্তিতে উল্লেখ করুন।</p></section><section><h2>তথ্য হালনাগাদ</h2><p>নতুন তথ্য, সংশোধন বা প্রাসঙ্গিক ছবি যোগ করতে এই পৃষ্ঠাটি ড্যাশবোর্ডের Page সেকশন থেকে সম্পাদনা করুন। নির্দিষ্ট তথ্যের উৎস ও সর্বশেষ হালনাগাদের তারিখ উল্লেখ করা ভালো।</p></section><style>.village-page-content{color:#263238;line-height:1.8;font-size:16px}.village-page-content .page-draft-note{padding:12px 14px;border-left:4px solid #b7791f;background:#fff8e6;border-radius:6px;font-size:14px}.village-page-content .page-lead{font-size:18px;color:#374151}.village-page-content section{margin:22px 0;padding:18px 20px;border:1px solid #e5e7eb;border-radius:12px;background:#fff}.village-page-content h2{margin:0 0 10px;color:#234e52;font-size:22px}.village-page-content p{margin:0 0 10px}.village-page-content p:last-child{margin-bottom:0}@media(max-width:600px){.village-page-content section{padding:14px}.village-page-content h2{font-size:19px}.village-page-content .page-lead{font-size:16px}}</style></div>','public','[]'::jsonb),
('Terms of Use','ওয়েবসাইটের কনটেন্ট ব্যবহার, জমা দেওয়া তথ্য ও ব্যবহারকারীর দায়িত্বের খসড়া শর্ত।','terms-of-use','<div class="village-page-content"><p class="page-draft-note"><strong>সম্পাদনার নোট:</strong> এটি একটি প্রাথমিক ধারণাগত খসড়া। বাস্তব নাম, সংখ্যা, ঠিকানা, যোগাযোগ ও অন্যান্য স্থানীয় তথ্য যাচাই করে আপডেট করুন।</p><p class="page-lead">এই পৃষ্ঠাটি ওয়েবসাইট ব্যবহারের শর্তের প্রাথমিক খসড়া। প্রকাশের আগে ওয়েবসাইটের প্রকৃত কার্যক্রম, কনটেন্ট ব্যবহারের অধিকার এবং প্রযোজ্য আইন অনুযায়ী পর্যালোচনা করুন।</p><section><h2>কনটেন্ট ও দায়িত্ব</h2><p>ব্যবহারকারী জমা দেওয়া তথ্যের নির্ভুলতা ও অধিকার সম্পর্কে দায়িত্বশীল থাকবেন—এ বিষয়ে সুনির্দিষ্ট শর্ত লিখুন। অন্যের কপিরাইট বা ব্যক্তিগত গোপনীয়তা লঙ্ঘনকারী উপাদান প্রকাশ করা যাবে কি না, তা স্পষ্ট করুন।</p></section><section><h2>পরিবর্তন ও সীমাবদ্ধতা</h2><p>ওয়েবসাইটের তথ্য সংশোধন, সেবা পরিবর্তন, ত্রুটি জানানো এবং শর্ত হালনাগাদের পদ্ধতি নির্ধারণ করুন। প্রয়োজনে আইনগত পরামর্শ নিয়ে চূড়ান্ত করুন।</p></section><section><h2>তথ্য হালনাগাদ</h2><p>নতুন তথ্য, সংশোধন বা প্রাসঙ্গিক ছবি যোগ করতে এই পৃষ্ঠাটি ড্যাশবোর্ডের Page সেকশন থেকে সম্পাদনা করুন। নির্দিষ্ট তথ্যের উৎস ও সর্বশেষ হালনাগাদের তারিখ উল্লেখ করা ভালো।</p></section><style>.village-page-content{color:#263238;line-height:1.8;font-size:16px}.village-page-content .page-draft-note{padding:12px 14px;border-left:4px solid #b7791f;background:#fff8e6;border-radius:6px;font-size:14px}.village-page-content .page-lead{font-size:18px;color:#374151}.village-page-content section{margin:22px 0;padding:18px 20px;border:1px solid #e5e7eb;border-radius:12px;background:#fff}.village-page-content h2{margin:0 0 10px;color:#234e52;font-size:22px}.village-page-content p{margin:0 0 10px}.village-page-content p:last-child{margin-bottom:0}@media(max-width:600px){.village-page-content section{padding:14px}.village-page-content h2{font-size:19px}.village-page-content .page-lead{font-size:16px}}</style></div>','public','[]'::jsonb),
('FAQ','Dalimgari ওয়েবসাইট ও গ্রামের তথ্য সম্পর্কে সাধারণ প্রশ্নোত্তর।','faq','<div class="village-page-content"><p class="page-draft-note"><strong>সম্পাদনার নোট:</strong> এটি একটি প্রাথমিক ধারণাগত খসড়া। বাস্তব নাম, সংখ্যা, ঠিকানা, যোগাযোগ ও অন্যান্য স্থানীয় তথ্য যাচাই করে আপডেট করুন।</p><p class="page-lead">এই পৃষ্ঠায় ওয়েবসাইট ব্যবহার, তথ্য সংশোধন, ছবি জমা দেওয়া এবং গ্রামের তথ্যের নির্ভরযোগ্যতা সম্পর্কে সাধারণ প্রশ্নের উত্তর রাখা হবে।</p><section><h2>কীভাবে তথ্য যোগ করব?</h2><p>ওয়েবসাইটের নির্ধারিত যোগাযোগের মাধ্যমে তথ্য, উৎস এবং প্রাসঙ্গিক তারিখ পাঠান। প্রকাশের আগে তথ্য যাচাই করা হতে পারে।</p></section><section><h2>তথ্যে ভুল থাকলে কী করব?</h2><p>ভুল তথ্যের পৃষ্ঠার নাম, সঠিক তথ্যের প্রমাণ বা উৎস এবং সংশোধনের অনুরোধ পাঠান।</p></section><section><h2>ছবি বা ব্যক্তিগত তথ্য প্রকাশ করা যাবে?</h2><p>প্রাসঙ্গিক অনুমতি ও অধিকার নিশ্চিত করে তবেই ছবি বা ব্যক্তিগত তথ্য জমা দিন।</p></section><section><h2>তথ্য হালনাগাদ</h2><p>নতুন তথ্য, সংশোধন বা প্রাসঙ্গিক ছবি যোগ করতে এই পৃষ্ঠাটি ড্যাশবোর্ডের Page সেকশন থেকে সম্পাদনা করুন। নির্দিষ্ট তথ্যের উৎস ও সর্বশেষ হালনাগাদের তারিখ উল্লেখ করা ভালো।</p></section><style>.village-page-content{color:#263238;line-height:1.8;font-size:16px}.village-page-content .page-draft-note{padding:12px 14px;border-left:4px solid #b7791f;background:#fff8e6;border-radius:6px;font-size:14px}.village-page-content .page-lead{font-size:18px;color:#374151}.village-page-content section{margin:22px 0;padding:18px 20px;border:1px solid #e5e7eb;border-radius:12px;background:#fff}.village-page-content h2{margin:0 0 10px;color:#234e52;font-size:22px}.village-page-content p{margin:0 0 10px}.village-page-content p:last-child{margin-bottom:0}@media(max-width:600px){.village-page-content section{padding:14px}.village-page-content h2{font-size:19px}.village-page-content .page-lead{font-size:16px}}</style></div>','public','[]'::jsonb)
ON CONFLICT (url) DO UPDATE
SET title = EXCLUDED.title,
    description = EXCLUDED.description,
    content = EXCLUDED.content,
    visibility = EXCLUDED.visibility,
    media = EXCLUDED.media,
    updated_at = now()
WHERE NULLIF(btrim(public.pages.content), '') IS NULL;

NOTIFY pgrst, 'reload schema';
COMMIT;
